import { afterEach, describe, expect, it, vi } from "vitest";
import { generateQr } from "../src/engines/qr/encode";
import reader from "../src/tools/qr-reader/module";

// Independent qrcode@1.5.4 renderer: 29x29, level M (not generated by
// Strumentini's local encoder), URL https://esempio.it/zxing-279.
const independentM = [
  "11111110110100111010001111111",
  "10000010011000101000101000001",
  "10111010101111100100101011101",
  "10111010100111110001001011101",
  "10111010001110000011001011101",
  "10000010110101010110101000001",
  "11111110101010101010101111111",
  "00000000101000010100100000000",
  "11010011010100110101011101101",
  "00111101110100011100010101000",
  "11000110100100000000011001011",
  "01001001101111100111111011000",
  "00100111111001001110010001110",
  "11000100111000100011100100110",
  "10011010010011011111101100001",
  "10010101110010101010011100010",
  "01101111001101111110110010000",
  "10011101111001001101000000111",
  "11000111011111010001001110111",
  "10111100010011111000111001101",
  "10000011111010111000111111111",
  "00000000000000001001100010000",
  "11111110110101000011101010011",
  "10000010010100111111100010110",
  "10111010010100011000111111010",
  "10111010100010001100111101010",
  "10111010001011100111110010100",
  "10000010101001111100011111011",
  "11111110110101100000010110100",
] as const;

function pixelsFor(rows: readonly string[], scale = 6) {
  const width = (rows.length + 8) * scale;
  const data = new Uint8ClampedArray(width * width * 4);
  for (let y = 0; y < width; y++) {
    for (let x = 0; x < width; x++) {
      const dark = rows[Math.floor(y / scale) - 4]?.[Math.floor(x / scale) - 4] === "1";
      const index = (y * width + x) * 4;
      data[index] = data[index + 1] = data[index + 2] = dark ? 0 : 255;
      data[index + 3] = 255;
    }
  }
  return { width, height: width, data };
}

function fakeCanvasRuntime() {
  // Only the pixel-only browser interface ZXing uses is stubbed. The real
  // ZXing decoder runs against the independent input; no decoder mock exists.
  vi.stubGlobal("ImageData", class {
    constructor(readonly data: Uint8ClampedArray, readonly width: number, readonly height: number) {}
  });
  vi.stubGlobal("document", {
    createElement: () => {
      let imageData: { data: Uint8ClampedArray } | undefined;
      const context = {
        putImageData: (value: { data: Uint8ClampedArray }) => { imageData = value; },
        getImageData: () => imageData,
      };
      return { width: 0, height: 0, getContext: () => context };
    },
  });
}

afterEach(() => vi.unstubAllGlobals());

describe("ZXing offline QR fallback #279", () => {
  it("reads an independent EC-M symbol and states its metadata limits", async () => {
    fakeCanvasRuntime();
    const result = await reader.run({ pixels: pixelsFor(independentM) }, { defaults: {} }) as Record<string, unknown>;
    expect(result).toMatchObject({
      payload: "https://esempio.it/zxing-279",
      source: "image",
      errorCorrection: "M",
      errorCorrectionVerified: false,
      version: 0,
      mask: null,
      engineVersion: "zxing-browser-0.2.1",
    });
  });

  it("preserves hard input caps and explicit cancellation", async () => {
    fakeCanvasRuntime();
    await expect(reader.run({ pixels: { width: 8_000, height: 8_000, data: new Uint8ClampedArray(4) } }, { defaults: {} }))
      .rejects.toThrow("QR_IMAGE_TOO_LARGE");
    await expect(reader.run({ pixels: { width: 21, height: 21, data: "invalid" } }, { defaults: {} }))
      .rejects.toThrow("QR_INVALID_INPUT");
    const signal = AbortSignal.abort();
    await expect(reader.run({ pixels: pixelsFor(independentM) }, { defaults: {} }, signal))
      .rejects.toMatchObject({ name: "AbortError" });
  });

  it("refuses a blank image rather than inventing a decode", async () => {
    fakeCanvasRuntime();
    await expect(reader.run({ pixels: pixelsFor(Array.from({ length: 21 }, () => "0".repeat(21))) }, { defaults: {} }))
      .rejects.toThrow("QR_DECODE_FAILED");
  });

  it("keeps native Reed–Solomon evidence for supported EC-L symbols", async () => {
    fakeCanvasRuntime();
    const native = generateQr("https://esempio.it/qr-l");
    const result = await reader.run({ pixels: pixelsFor(native.matrixRows) }, { defaults: {} }) as Record<string, unknown>;
    expect(result).toMatchObject({
      payload: "https://esempio.it/qr-l",
      errorCorrection: "L",
      errorCorrectionVerified: true,
      maskFromFormatInformation: true,
    });
  });

  it("preserves the refusal for a deliberately altered EC-L symbol", async () => {
    fakeCanvasRuntime();
    const rows = [...generateQr("https://esempio.it/qr-l").matrixRows];
    rows[14] = rows[14]!.slice(0, 8) + (rows[14]![8] === "1" ? "0" : "1") + rows[14]!.slice(9);
    await expect(reader.run({ pixels: pixelsFor(rows) }, { defaults: {} }))
      .rejects.toThrow("QR_DECODE_FAILED");
  });
});
